@startuml
class Product {
  +name : string
  +description : string
  +netPrice : double
}

class Manufacturer {
  +name : string
}

class Country {
  +name : string
  +vatRate : float
  +currency : string
  +conversionRateToEuro : float
}

class Representative {
  +firstName : string
  +lastName : string
  +socialSecurityNumber : string
  +telephoneNumber : string
  +emailAddress : string
}

class Customer {
  +name : string
  +address : string
  +telephoneNumber : string
  +emailAddress : string
}

class Order {
  +orderId : string
  +orderQuantity : int
  +orderDate : date
  +desiredDeliveryDate : date
}

Product "0..*" -- "1" Manufacturer : manufactured by
Product "*" -- "*" Country : sold in
Product "1" -- "*" Order : refers to
Representative "1" -- "1" Country : responsible for
Representative "1" -- "*" Order : places
Customer "1" -- "*" Order : places
Customer "*" -- "*" Country : resells goods
@enduml

